@font-face {
  font-family: 'InterFallback';
  src: local('Arial');
  size-adjust: 102.5%;
  ascent-override: 95%;
  descent-override: 25%;
  line-gap-override: 0%;
}

body {
  font-family: 'Inter', 'InterFallback', sans-serif;
}

export function ResponsiveTourCard({ imageUrl, title }: { imageUrl: string; title: string }) {
  return (
    <div className="overflow-hidden rounded-xl bg-slate-900 border border-slate-800">
      <div className="relative w-full aspect-[16/9] bg-slate-800">
        <img
          src={imageUrl}
          alt={title}
          loading="lazy"
          className="absolute inset-0 h-full w-full object-cover"
        />
      </div>
      <div className="p-4">
        <h3 className="text-lg font-semibold text-white">{title}</h3>
      </div>
    </div>
  );
}
